using System;using System.Linq;using System.Collections.Generic;using System.Text.Json;using Deception.Core;using Deception.PolyModAdapter;
using U=Polytopia.Data.UnitData.Type;using T=Polytopia.Data.TerrainData.Type;
namespace Deception.Tests {
 public static partial class MimicMovementTests {
 static int Assertions;static readonly List<string> Cases=new();static void Check(bool b,string why){Assertions++;if(!b)throw new Exception(why);}static void Test(string name,Action f){try{f();Cases.Add(name);}catch(Exception e){throw new Exception(name,e);}}
 sealed record Rig(GameState S,UnitState U,TileData Source,TileData Land,TileData Water);
 static Rig Make(string form="island",T source=T.field,string? genuine=null){RecruitmentHooks.Reset();Fault.At="";NativeGameStateEnvelope.Frames.Clear();NativeRegroupSession.Enabled=NativeRegroupSession.Admitted=true;NativeMimicWaterMovement.Clear();NativeMimicMovement.Clear();NativeDisguiseMovement.Clear();PathFinder.ThrowQuery=PathFinder.CarrierDetour=false;PathFinder.Queries=0;PathFinder.During=null;
  NativeShedDisguise.PreparePresentation=null;NativeDisguiseMovement.PreparePresentation=null;
  PathFinder.NullForNoPath=false;
  var s=new GameState();NativeRegroupSession.Owned=GameManager.GameState=s;NativeRegroupSession.Faults.Clear();var src=new TileData{coordinates=new(1,1),terrain=source,IsWater=source is T.water or T.ocean};var land=new TileData{coordinates=new(2,1)};var water=new TileData{coordinates=new(1,2),terrain=T.water,IsWater=true};s.Map.Tiles.AddRange(new[]{src,land,water});
  var data=RecruitmentHooks.Definitions[genuine??RecruitmentCatalog.Variant(form)];var u=new UnitState{id=7,type=data.type,UnitData=data,coordinates=src.coordinates,health=genuine is null?(ushort)10:(ushort)100};src.unit=u;
  var artData=RecruitmentHooks.Definitions[form];var art=new LedgerAppearance(form,new("Elyrion","DarkElf"),new("Elyrion","DarkElf"),new("Elyrion","DarkElf"),57,(ushort)artData.health,(ushort)artData.health,false,ApparentConcealment.Visible,-1,Array.Empty<string>());
  var row=new LedgerUnit(8,7,true,genuine is null?LedgerActualKind.Mimic:LedgerActualKind.Genuine,true,art,PaidInvestmentKind.Known,13);var l=new NativeIdentityLedger(Guid.Parse("a3ca461f-fd6b-44be-8b87-d4483d12f50b"),9,1,new[]{row},Array.Empty<LedgerReceipt>());NativeGameStateEnvelope.Set(s,4,NativeIdentityLedgerCodec.Encode(l,4));return new(s,u,src,land,water);}
 static LedgerUnit Row(Rig r){var p=NativeGameStateEnvelope.Get(r.S)!;return NativeIdentityLedgerCodec.Decode(p.Bytes(),p.Revision).Units.Single();}
 static void Edit(Rig r,Func<LedgerUnit,LedgerUnit> f){var p=NativeGameStateEnvelope.Get(r.S)!;var l=NativeIdentityLedgerCodec.Decode(p.Bytes(),p.Revision);NativeGameStateEnvelope.Set(r.S,p.Revision,NativeIdentityLedgerCodec.Encode(l with{Units=l.Units.Select(f).ToArray()},p.Revision));}
 static void Wrap(Rig r){var art=NativeMimicTransport.EmbarkAppearance(r.S,Row(r).Appearance!);r.U.type=U.dcp_mimic_form_transportship;r.U.UnitData=RecruitmentHooks.Definitions[r.U.type.ToString()];r.U.passengerUnit=new(){id=6,type=U.dcp_mimic_form_warrior,UnitData=RecruitmentHooks.Definitions["dcp_mimic_form_warrior"],health=10,home=r.U.home,coordinates=r.U.coordinates};Edit(r,x=>x with{Transport=new(6),Appearance=art});}
 static object[] Options(Rig r)=>Native.Items(PathFinder.GetMoveOptions(r.S,r.U.coordinates,UnitDataExtensions.GetMovement(r.U,r.S),r.U)).ToArray();
 static bool Has(object[] list,TileData t)=>list.Cast<WorldCoordinates>().Any(x=>x.X==t.coordinates.X&&x.Y==t.coordinates.Y);
 static MoveCommand Cmd(Rig r,TileData dest)=>new(){UnitId=r.U.id,PlayerId=1,From=r.U.coordinates,To=dest.coordinates};
 static void Stable(Rig r,byte[] before,string native){Check(before.SequenceEqual(NativeGameStateEnvelope.Get(r.S)!.Bytes()),"query changed ledger");Check(TransportStateDump.Dump(r.S)==native,"query changed native state");}
 public static int Run(){try{
  NativeMimicMovement.Install(new HarmonyLib.Harmony());
  foreach(var origin in new[]{T.field,T.water})Test("island-city-"+origin+"-land-fallback",()=>{var r=Make(source:origin);r.Source.City=true;var before=NativeGameStateEnvelope.Get(r.S)!.Bytes();var native=TransportStateDump.Dump(r.S);var options=Options(r);Check(Has(options,r.Land)&&!Has(options,r.Water),"city must offer actual land move but not locked water");Stable(r,before,native);var c=Cmd(r,r.Land);Check(c.IsValid(r.S,out _),"fallback command must pass installed policy");var a=c.Execute(r.S);Check(r.Land.unit==r.U&&r.U.type==U.dcp_mimic&&Row(r).Appearance?.Form==RecruitmentCatalog.MenuId,"accepted move must expose actual land body");Check(r.U.moved&&!r.U.attacked&&r.U.health==10&&Row(r).PaidStars==13&&Row(r).LogicalId==8,"land shed retains native movement spent and true identity");Check(a.CoastChildren==0,"no stale coast child queued");});
  Test("synthetic-zero-native-movement-still-queries-real-step",()=>{var r=Make("dragonegg");r.U.UnitData.movement=RecruitmentHooks.Definitions["dragonegg"].movement=0;Check(r.U.UnitData.movement==0&&Has(Options(r),r.Land),"zero native apparent movement must still reach the fallback query");Cmd(r,r.Land).Execute(r.S);Check(r.U.type==U.dcp_mimic&&Row(r).Appearance?.Form==RecruitmentCatalog.MenuId,"native queued egg fallback sheds");});
  Test("cloak-city-uses-exact-fallback-not-carrier-detour",()=>{var r=Make("cloak");r.Land.City=true;r.Land.owner=2;r.Water.terrain=T.field;r.Water.IsWater=false;PathFinder.CarrierDetour=true;var c=Cmd(r,r.Land);Check(c.IsValid(r.S,out _),"real direct route available");var a=c.Execute(r.S);Check(a.Path.Count==2&&a.Path[0].X==2,"execution uses exact real direct path, not longer carrier route");Check(Row(r).Appearance?.Form==RecruitmentCatalog.MenuId,"fallback admission cannot silently retain incompatible mask");});
  Test("apparent-frozen-flight-limited-to-real-options",()=>{var r=Make("firedragon");var p=NativeGameStateEnvelope.Get(r.S)!;var l=NativeIdentityLedgerCodec.Decode(p.Bytes(),p.Revision);l=l with{Units=l.Units.Select(x=>x with{Appearance=x.Appearance! with{Effects=new[]{"Frozen"}}}).ToArray()};NativeGameStateEnvelope.Set(r.S,p.Revision,NativeIdentityLedgerCodec.Encode(l,p.Revision));Check(Has(Options(r),r.Land)&&!Has(Options(r),r.Water),"fake frozen flight cannot silently supply unsupported options");Cmd(r,r.Land).Execute(r.S);Check(Row(r).Appearance?.Form==RecruitmentCatalog.MenuId,"real fallback sheds fake Frozen");});
  foreach(bool other in new[]{false,true})Test("rogue-road-fallback-self-identity-"+other,()=>{var r=Make();r.Land.Cost=3;var mid=new TileData{coordinates=new(3,1),Cost=3};var far=new TileData{coordinates=new(4,1),Cost=3};r.S.Map.Tiles.AddRange(new[]{mid,far});var p=NativeGameStateEnvelope.Get(r.S)!;var l=NativeIdentityLedgerCodec.Decode(p.Bytes(),p.Revision);l=l with{Units=l.Units.Select(x=>x with{Rogue=new LedgerRogue(2,1,4)}).ToArray()};NativeGameStateEnvelope.Set(r.S,p.Revision,NativeIdentityLedgerCodec.Encode(l,p.Revision));if(other)r.S.Map.Tiles.Add(new(){coordinates=new(2,2),unit=new(){id=9,coordinates=new(2,2)}});Check(Has(Options(r),far)==!other,"detached real source is self, while another unit still exerts Rogue ZOC");Check(Cmd(r,far).IsValid(r.S,out _)==!other,"preview and command apply same Rogue route restriction");});
  Test("native-one-movement-budget",()=>{var r=Make();var far=new TileData{coordinates=new(3,1)};r.S.Map.Tiles.Add(far);var options=Options(r);Check(Has(options,r.Land)&&!Has(options,far),"native base one-move radius enforced");Check(!Cmd(r,far).IsValid(r.S,out _),"command cannot stretch fallback to apparent Island movement2");});
  Test("native-final-cost-overshoot",()=>{var r=Make();r.Land.Cost=20;Check(Has(Options(r),r.Land),"native final forest-cost entry allowed");Cmd(r,r.Land).Execute(r.S);Check(Row(r).Appearance?.Form==RecruitmentCatalog.MenuId,"costly final step sheds");});
  Test("apparent-flight-preserved",()=>{var r=Make("firedragon");var far=new TileData{coordinates=new(3,1),terrain=T.water,IsWater=true};r.S.Map.Tiles.Add(far);Check(Has(Options(r),far)&&Has(Options(r),r.Water),"native flight still offers unresearched water beyond base range");Cmd(r,far).Execute(r.S);Check(Row(r).Appearance?.Form=="firedragon"&&r.U.type==U.dcp_mimic_form_firedragon,"compatible flight never sheds");});
  Test("apparent-swim-after-research",()=>{var r=Make();r.S.Player.Water=true;Check(Has(Options(r),r.Water)&&Has(Options(r),r.Land),"both independent movement sets available");Cmd(r,r.Water).Execute(r.S);Check(Row(r).Appearance?.Form=="island"&&r.U.type==U.dcp_mimic_form_island,"native apparent route wins without shed");});
  foreach(string blocked in new[]{"occupied","hidden","blocked","moved","frozen","foreign","unready"})Test("deny-"+blocked,()=>{var r=Make();switch(blocked){case"occupied":r.Land.unit=new(){id=10};break;case"hidden":r.Land.Explored=false;break;case"blocked":r.Land.Blocked=true;break;case"moved":r.U.moved=true;break;case"frozen":r.U.effects.Add(UnitEffect.Frozen);break;case"foreign":r.U.owner=2;break;case"unready":NativeRegroupSession.Admitted=false;break;}Check(!Cmd(r,r.Land).IsValid(r.S,out _),"fallback cannot override native denial");Check(Row(r).Appearance?.Form=="island","denied move retains mask");});
  foreach(string cancel in new[]{"skip","no-move","throw","unqueued","invalid","push"})Test("canceled-"+cancel,()=>{var r=Make();int cues=0;NativeDisguiseMovement.PreparePresentation=(s,u)=>()=>cues++;NativeShedDisguise.PreparePresentation=(s,u)=>()=>cues++;var a=new MoveAction{UnitId=7,Path=PathFinder.GetPath(r.S,r.Source.coordinates,r.Land.coordinates,2,r.U)};if(cancel!="unqueued")r.S.ActionStack.Add(a);a.Skip=cancel=="skip";a.NoMove=cancel=="no-move";a.Fail=cancel=="throw";a.Valid=cancel!="invalid";if(cancel=="push")a.Reason=MoveAction.MoveReason.Push;try{a.Execute(r.S);}catch when(cancel=="throw"){}Check(Row(r).Appearance?.Form=="island"&&r.U.type==U.dcp_mimic_form_island,"nonaccepted move must not shed");Check(!NativeDisguiseMovement.IsShedding(r.S,r.U),"scope cleared");Check(cues==0,"unaccepted movement emitted successful shed cue");});
  Test("stale-endpoint-and-owner",()=>{var r=Make();var a=new MoveAction{UnitId=7,Path=PathFinder.GetPath(r.S,r.Source.coordinates,r.Land.coordinates,2,r.U),During=(s,u)=>u.owner=2};r.S.ActionStack.Add(a);a.Execute(r.S);Check(Row(r).Appearance?.Form=="island","ownership change cancels private finalizer");});
  Test("detached-query-is-not-authority",()=>{var r=Make();var fake=(UnitState)Native.DetachedClone(r.U,"UnitState");Check(!Native.Items(PathFinder.GetMoveOptions(r.S,r.Source.coordinates,5,fake)).Any(),"arbitrary detached clone rejected");Check(r.U.type==U.dcp_mimic_form_island,"actual source untouched");});
  Test("query-exception-cleans-scope",()=>{var r=Make();PathFinder.ThrowQuery=true;try{Options(r);throw new Exception("expected throw");}catch(Exception e)when(e.Message=="query failed"){}PathFinder.ThrowQuery=false;Check(Has(Options(r),r.Land),"next query recovers after exception");});
  Test("query-frame-change-invalidates-detached-results",()=>{var r=Make();bool changed=false;PathFinder.During=(s,u)=>{if(u==r.U||changed)return;changed=true;var p=NativeGameStateEnvelope.Get(s)!;NativeGameStateEnvelope.Set(s,p.Revision,p.Bytes());};Check(!Has(Options(r),r.Land),"stale detached frame cannot add destinations");PathFinder.During=null;Check(Has(Options(r),r.Land),"fresh query uses replacement authenticated frame");});
  Test("genuine-unit-no-extra-flight",()=>{var r=Make("firedragon",genuine:"warrior");Check(!Has(Options(r),r.Water),"genuine Warrior cannot inherit dragon path");Check(!Cmd(r,r.Water).IsValid(r.S,out _),"genuine movement stays native");});
  Test("cloak-city-fallback-and-peace",()=>{var r=Make("cloak");r.Land.City=true;r.Land.owner=2;Check(Has(Options(r),r.Land)&&Cmd(r,r.Land).IsValid(r.S,out _),"actual body may enter enemy city while shedding cloak restriction");var a=Cmd(r,r.Land).Execute(r.S);Check(Row(r).Appearance?.Form==RecruitmentCatalog.MenuId,"cloak mask shed before normal capture eligibility");Check(a.Sight==1,"fallback discovery uses exposed sight rather than old Cloak Scout");Check(UnitDataExtensions.GetSightRange(RecruitmentHooks.Definitions["cloak"])==2,"ordinary Scout getter unaffected outside exact move");r=Make("cloak");r.Land.City=true;r.Land.owner=2;r.S.Player.relations[2]=new(){State=1};Check(!Has(Options(r),r.Land)&&!Cmd(r,r.Land).IsValid(r.S,out _),"native peace endpoint veto retained");});
  Test("frozen-apparent-land-to-port-conversion",()=>{var r=Make("warrior");r.S.Player.Water=true;r.Water.Port=true;var p=NativeGameStateEnvelope.Get(r.S)!;var l=NativeIdentityLedgerCodec.Decode(p.Bytes(),p.Revision);l=l with{Units=l.Units.Select(x=>x with{Appearance=x.Appearance! with{Effects=new[]{"Frozen"}}}).ToArray()};NativeGameStateEnvelope.Set(r.S,p.Revision,NativeIdentityLedgerCodec.Encode(l,p.Revision));var a=Cmd(r,r.Water).Execute(r.S);var boat=r.Water.unit!;Check(a.CoastChildren==0&&boat!=r.U&&boat.passengerUnit==r.U,"one atomic conversion instead of old queued native converter");Check(boat.type==U.dcp_mimic_form_transportship&&r.U.type==U.dcp_mimic&&Row(r).Transport?.PassengerNativeId==7,"wrapper and cargo use exposed identity");Check(boat.moved&&boat.attacked&&boat.health==10&&Row(r).Appearance?.Passenger?.Form==RecruitmentCatalog.MenuId,"native shore exhaustion and 1HP retained");});
  foreach(bool fail in new[]{false,true})Test("swimming-water-to-land-"+fail,()=>{var r=Make("island",T.water);r.S.Player.Water=true;Check(Has(Options(r),r.Land),"native exposed raft can land despite Island mask");if(fail)Fault.At="validation";try{Cmd(r,r.Land).Execute(r.S);}catch when(fail){}if(!fail){Check(r.Land.unit==r.U&&r.U.type==U.dcp_mimic&&r.U.passengerUnit==null,"non-wrapper swimming identity lands as exposed Mimic");Check(r.U.moved&&r.U.attacked&&Row(r).Transport==null,"actual shore exhaustion applies without inventing a wrapper");}else{Check(r.U.type==U.dcp_mimic_form_island&&r.U.moved&&!r.U.attacked,"failed conversion restores flags to just native movement spent");Check(Row(r).Appearance?.Form=="island","failed non-wrapper shed restores appearance");}});
  foreach(bool fail in new[]{false,true})Test("water-raft-landing-"+fail,()=>{var r=Make("warrior",T.water);r.S.Player.Water=true;var p=NativeGameStateEnvelope.Get(r.S)!;var l=NativeIdentityLedgerCodec.Decode(p.Bytes(),p.Revision);var art=NativeMimicTransport.EmbarkAppearance(r.S,Row(r).Appearance!);r.U.type=U.dcp_mimic_form_transportship;r.U.UnitData=RecruitmentHooks.Definitions[r.U.type.ToString()];var cargo=new UnitState{id=6,type=U.dcp_mimic_form_warrior,UnitData=RecruitmentHooks.Definitions["dcp_mimic_form_warrior"],health=10,home=r.U.home};r.U.passengerUnit=cargo;l=l with{Units=l.Units.Select(x=>x with{Transport=new(6),Appearance=art with{Effects=new[]{"Frozen"}}}).ToArray()};NativeGameStateEnvelope.Set(r.S,p.Revision,NativeIdentityLedgerCodec.Encode(l,p.Revision));var cmd=Cmd(r,r.Land);if(fail)Fault.At="validation";try{cmd.Execute(r.S);}catch when(fail){}if(!fail){Check(r.Land.unit==cargo&&cargo.type==U.dcp_mimic&&cargo.moved&&cargo.attacked,"landing restores original cargo exhausted");Check(Row(r).NativeId==6&&Row(r).Transport==null&&Row(r).PaidStars==13,"ledger rebind retains logical paid identity");}else{Check(r.Land.unit==r.U&&r.U.passengerUnit==cargo&&Row(r).Appearance?.Form=="transportship","failed shed restores pre-conversion body and appearance at moved endpoint");Check(r.U.moved&&!r.U.attacked&&!cargo.attacked,"failed shore transaction restores action flags");}});
  foreach(bool boat in new[]{false,true})foreach(bool city in new[]{false,true})foreach(bool rawWater in new[]{false,true})Test($"flood-move-keeps-mode-{boat}-{city}-{rawWater}",()=>{
   var r=Make("warrior",boat?T.water:T.field);r.S.Player.Water=true;if(boat)Wrap(r);r.Land.Wetland=true;r.Land.City=city;r.Land.IsWater=rawWater;r.Land.terrain=rawWater?T.water:T.field;r.Land.Port=true;
   var before=Row(r);var cargo=r.U.passengerUnit;Check(Has(Options(r),r.Land)&&Cmd(r,r.Land).IsValid(r.S,out _),"native wetland destination must remain reachable");
   var a=Cmd(r,r.Land).Execute(r.S);var after=Row(r);Check(a.CoastChildren==0&&r.Land.unit==r.U&&r.U.passengerUnit==cargo,"flood movement must not enqueue shore conversion");
   Check(after.NativeId==before.NativeId&&after.Transport==before.Transport&&after.Appearance!.Form==before.Appearance!.Form&&r.U.health==10,"flood move changed apparent mode or native identity");
   Check(NativeMimicTransport.ExposedBoat(r.Land,after)==boat,"actual flood artwork mode differs from existing body");
  });
  Test("flooded-land-island-real-fallback-stays-land",()=>{var r=Make();r.Source.Wetland=true;Check(Has(Options(r),r.Land),"land body on flood must use land fallback without Fishing");Cmd(r,r.Land).Execute(r.S);Check(Row(r).Appearance?.Form==RecruitmentCatalog.MenuId&&Row(r).Transport==null,"flood wrongly inferred exposed raft");});
  Test("shed-flooded-boat-keeps-wrapper",()=>{var r=Make("warrior",T.water);Wrap(r);r.Source.Wetland=true;r.Source.IsWater=false;r.Source.terrain=T.field;var cargo=r.U.passengerUnit;Check(NativeShedDisguise.TryOffer(r.S,7,out var intent,out var why)&&NativeShedDisguise.TryCommit(r.S,intent!,out _,out why),"flooded boat shed rejected: "+why);Check(r.Source.unit==r.U&&r.U.passengerUnit==cargo&&Row(r).Transport?.PassengerNativeId==6&&Row(r).Appearance?.Passenger?.Form==RecruitmentCatalog.MenuId,"voluntary flood shed must retain physical vessel with exposed cargo");});
  foreach(string form in new[]{"warrior","island"})Test("mermimic-portless-real-water-fallback-"+form,()=>{var r=Make(form);Edit(r,x=>x with{AmphibiousMimic=true});var before=TransportStateDump.Dump(r.S);var saved=NativeGameStateEnvelope.Get(r.S)!.Bytes();Check(Has(Options(r),r.Water)&&Has(Options(r),r.Land),"amphibious actual body must supply native land/water routes without generic boat tech gate");Stable(r,saved,before);var a=Cmd(r,r.Water).Execute(r.S);Check(r.Water.unit==r.U&&r.U.type==U.dcp_mermimic&&r.U.passengerUnit==null&&Row(r).Transport==null&&Row(r).AmphibiousMimic,"amphibious fallback invented boat or lost body origin");Check(Row(r).Appearance?.Form==AquarionCatalog.MimicId&&r.U.health==10&&r.U.moved&&!r.U.attacked&&a.CoastChildren==0,"amphibious movement shed changed action history or actual stats");});
  foreach(bool fail in new[]{false,true})Test("mermimic-shed-ship-on-water-"+fail,()=>{var r=Make("warrior",T.water);Edit(r,x=>x with{AmphibiousMimic=true});Wrap(r);var cargo=r.U.passengerUnit!;var before=TransportStateDump.Dump(r.S);byte[] saved=NativeGameStateEnvelope.Get(r.S)!.Bytes();Check(NativeShedDisguise.TryOffer(r.S,7,out var intent,out var why),"ship disguise should offer shed");if(fail)Fault.At="validation";bool ok=NativeShedDisguise.TryCommit(r.S,intent!,out _,out why);Check(ok==!fail,"wrong amphibious shed transaction result "+why);if(fail){Check(before==TransportStateDump.Dump(r.S)&&saved.SequenceEqual(NativeGameStateEnvelope.Get(r.S)!.Bytes()),"failed amphibious landing must restore exact wrapper/cargo/frame");}else{Check(r.Source.unit==cargo&&cargo.type==U.dcp_mermimic&&cargo.passengerUnit==null&&Row(r).NativeId==6&&Row(r).Transport==null,"water shed did not restore original amphibious cargo identity");Check(Row(r).AmphibiousMimic&&Row(r).LogicalId==8&&Row(r).PaidStars==13&&cargo.health==10&&!cargo.moved&&!cargo.attacked,"amphibious shed changed investment/history or spent action");Check(!NativeMimicTransport.ExposedBoat(r.Source,Row(r))&&NativeShedDisguise.Exposed(Row(r).Appearance),"exposed Mermimic retained boat appearance");}});
  Test("bare-mermimic-water-native-movement-never-boards",()=>{var r=Make("warrior",T.water);r.U.type=U.dcp_mermimic;r.U.UnitData=RecruitmentHooks.Definitions[AquarionCatalog.MimicId];Edit(r,x=>x with{AmphibiousMimic=true,Appearance=x.Appearance! with{Form=AquarionCatalog.MimicId,Health=10,Maximum=10}});r.Water.Port=true;Check(Has(Options(r),r.Land)&&Has(Options(r),r.Water),"exposed amphibious land/water route missing");var a=Cmd(r,r.Water).Execute(r.S);Check(a.CoastChildren==0&&r.Water.unit==r.U&&r.U.type==U.dcp_mermimic&&Row(r).Transport==null,"bare amphibious unit automatically boarded");});
  foreach(bool startingWater in new[]{false,true})Test("flying-mimic-flood-retains-incoming-"+(startingWater?"boat":"land"),()=>{
   var r=Make("firedragon",startingWater?T.water:T.field);r.Land.Wetland=true;
   var a=new MoveAction{UnitId=7,PlayerId=1,Path=(Il2CppSystem.Collections.Generic.List<WorldCoordinates>)Native.NewList("WorldCoordinates",new object[]{r.Land.coordinates,r.Source.coordinates})};r.S.ActionStack.Add(a);a.Execute(r.S);
   Check(Row(r).MimicWaterForm==startingWater&&Row(r).Transport==null,"flight lost incoming independent mode");
   Check(NativeMimicTransport.ExposedBoat(r.Land,Row(r))==startingWater&&r.U.type==U.dcp_mimic_form_firedragon,"flood mode altered apparent form");
   var p=NativeGameStateEnvelope.Get(r.S)!;NativeGameStateEnvelope.Set(r.S,p.Revision,p.Bytes());Check(Row(r).MimicWaterForm==startingWater,"serialized mode changed");
  });
  Test("flying-crosses-openwater-then-flood-records-nearest-ordinary-cell",()=>{
   var r=Make("firedragon");r.Land.coordinates=new(2,2);r.Land.Wetland=true;
   var a=new MoveAction{UnitId=7,PlayerId=1,Path=(Il2CppSystem.Collections.Generic.List<WorldCoordinates>)Native.NewList("WorldCoordinates",new object[]{r.Land.coordinates,r.Water.coordinates,r.Source.coordinates})};r.S.ActionStack.Add(a);a.Execute(r.S);
   Check(Row(r).MimicWaterForm&&Row(r).Transport==null&&NativeMimicTransport.ExposedBoat(r.Land,Row(r)),"intermediate openwater was ignored");
   Check(Row(r).Appearance!.Form=="firedragon"&&r.U.health==10&&!r.U.attacked,"water mode changed combat or disguise");
   Check(NativeShedDisguise.TryOffer(r.S,7,out var intent,out var why),why);Check(NativeShedDisguise.TryCommit(r.S,intent!,out _,out why),why);
   Check(Row(r).MimicWaterForm&&Row(r).Transport!=null&&r.Land.unit!.passengerUnit==r.U,"shedding flight on flood failed to retain boat");
  });
  foreach(string failure in new[]{"skip","fail","no-move","stale"})Test("water-mode-not-written-on-"+failure,()=>{
   var r=Make("firedragon");r.Land.Wetland=true;r.Land.coordinates=new(2,2);
   var a=new MoveAction{UnitId=7,PlayerId=1,Path=(Il2CppSystem.Collections.Generic.List<WorldCoordinates>)Native.NewList("WorldCoordinates",new object[]{r.Land.coordinates,r.Water.coordinates,r.Source.coordinates}),Skip=failure=="skip",Fail=failure=="fail",NoMove=failure=="no-move"};
   if(failure=="stale")a.During=(state,unit)=>NativeMimicMovement.Clear();r.S.ActionStack.Add(a);var frame=NativeGameStateEnvelope.Get(r.S)!.Bytes();try{a.Execute(r.S);}catch{if(failure!="fail")throw;}
   Check(!Row(r).MimicWaterForm&&NativeGameStateEnvelope.Get(r.S)!.Bytes().SequenceEqual(frame),"unaccepted mode was published");
  });
  foreach(bool genuine in new[]{false,true})Test("successful-move-presentation-follows-committed-shed-"+genuine,()=>{
   var r=Make(genuine:genuine?"warrior":null);int prepared=0,played=0;bool before=false,after=false;
   NativeDisguiseMovement.PreparePresentation=(state,unit)=>{prepared++;before=r.Source.unit==r.U&&Row(r).Independent;return ()=>{played++;after=r.Land.unit==r.U&&(genuine?!Row(r).Independent:NativeShedDisguise.Exposed(Row(r).Appearance));};};
   Cmd(r,r.Land).Execute(r.S);Check(prepared==1&&before,"move cue did not capture original visible event extent");Check(played==1&&after,"move cue did not follow successful real reveal");
  });
  foreach(bool fail in new[]{false,true})Test("transaction-cue-only-after-accepted-shed-"+fail,()=>{
   var r=Make("warrior",T.water);Edit(r,x=>x with{AmphibiousMimic=true});Wrap(r);int prepared=0,played=0;bool accepted=false;
   NativeShedDisguise.PreparePresentation=(state,unit)=>{prepared++;return ()=>{played++;accepted=Row(r).NativeId==6&&Row(r).Transport==null&&r.Source.unit!.type==U.dcp_mermimic;};};
   Check(NativeShedDisguise.TryOffer(r.S,7,out var intent,out var why),why);if(fail)Fault.At="counter";
   Check(NativeShedDisguise.TryCommit(r.S,intent!,out _,out why)==!fail,"wrong transaction outcome");Check(prepared==1&&played==(fail?0:1)&&(!accepted==fail),"rollback or incomplete transport emitted cue");
   if(!fail){Check(NativeShedDisguise.TryCommit(r.S,intent!,out _,out why),"repeat receipt rejected");Check(played==1&&prepared==1,"repeat receipt restarted capture/cue");}
  });
  Test("presentation-exceptions-cannot-roll-back-real-shed",()=>{
   var r=Make();NativeDisguiseMovement.PreparePresentation=(s,u)=>()=>throw new Exception("cosmetic playback");NativeShedDisguise.PreparePresentation=(s,u)=>throw new Exception("cosmetic capture");
   Cmd(r,r.Land).Execute(r.S);Check(r.Land.unit==r.U&&NativeShedDisguise.Exposed(Row(r).Appearance)&&r.U.moved,"cosmetic failure changed accepted movement");Check(NativeRegroupSession.Faults.Count==0&&!NativeDisguiseMovement.IsShedding(r.S,r.U),"cosmetic failure faulted backend or retained scope");
  });
  RogueNullPathTests();
  Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Cases.Count,assertions=Assertions,tests=Cases,nativeGame="NOT RUN"}));return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 }
